customCSS:
.t, .history { color: #6272a4; }
.join { color: #50fa7b; }
.part, .quit { color: #6272a4; }
.kick, .error { color: #ff5555; }
.notice { color: #f1fa8c; }
.action { color: #ff79c6; }
.mode, .nick, .topic, .server { color: #8be9fd; }
.highlight { color: #f8f8f2; background-color: #44475a; border-left: 3px solid #ff79c6; padding-left: 8px; }
.reply { color: #6272a4; border-left: 2px solid #8be9fd; padding-left: 6px; }
.oper { color: #282a36; background-color: #f1fa8c; }
.reactions { color: #8be9fd; background-color: #424450; }
.card { background-color: #424450; border-color: #6272a4; }
.card-title { color: #8be9fd; }
.card-desc { color: #6272a4; }
.daychange { color: #6272a4; border-color: #424450; }
